from openassembler.pyfront import *
@kernel
def i64_literal(a: Array(i64), out: Array(i64), delta: i64, n: i32):
    shared = shared_array(i64, 128)
    t = tid_x()
    i = ctaid_x() * 128 + t
    if t == 127:
        shared[127] = a[i]
    syncthreads()
    v = shared[127]
    if i < n:
        out[i * 4] = v

from openassembler.pyfront import *
@kernel
def i64_nested(a: Array(i64), out: Array(i64), delta: i64, n: i32):
    shared = shared_array(i64, 128)
    t = tid_x()
    i = ctaid_x() * 128 + t
    if t < 64:
        if t % 2 == 0:
            shared[t] = a[i] + delta
        else:
            shared[t] = a[i] - delta
    else:
        shared[t] = a[i]
    syncthreads()
    v = shared[t ^ 64]
    if i < n:
        out[i * 4] = v

